def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_condition(n):
    if n == 1:
        # n=1. Prime factorization is empty.
        # tau(1^12) = tau(1) = 1. 
        # n = 1. Condition 1 = 1 holds.
        return True

    factors = prime_factorization(n)

    # Check if n is odd, as required by the task.
    if n % 2 == 0:
        return None # Not an odd integer

    # Calculate RHS = tau(n^12)
    rhs = 1
    for prime, exponent in factors.items():
        # n = product(p_i^a_i)
        # n^12 = product(p_i^(12*a_i))
        # tau(n^12) = product(12*a_i + 1)
        rhs *= (12 * exponent + 1)

    # Check condition: n = tau(n^12)
    return n == rhs

results = {}
# Check odd integers n from 1 to 100
for n in range(1, 101, 2):
    result = check_condition(n)
    if result is True:
        results[n] = "Solution found"
    elif result is False:
        results[n] = "No solution"
    # If result is None, it means n was even, but loop handles this.

print(f"Odd integers n <= 100 satisfying the condition: {results}")

import math

def primorial(k):
    primes = []
    num = 2
    while len(primes) < k:
        is_prime = True
        for p in primes:
            if p * p > num:
                break
            if num % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
        num += 1
    return math.prod(primes)

def power(k):
    return 13**k

print("k | Primorial P_k# | 13^k | Inequality P_k# <= 13^k")
print("-" * 60)
for k in range(1, 15):
    p_k_hash = primorial(k)
    thirteen_k = power(k)
    result = "True" if p_k_hash <= thirteen_k else "False"
    print(f"{k:2} | {p_k_hash:14} | {thirteen_k:14} | {result}")
